<?php
namespace App\Services;
use App\Models\LeaveBalance; use App\Models\LeaveRequest; use App\Models\OrganizationMembership; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Validator; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException;
class LeaveService
{
    public function __construct(private WorkspaceAccess $access, private AuditRecorder $audit, private WorkspaceNotifications $notifications) {}
    public function request(OrganizationMembership $actor,array $input): LeaveRequest
    {
        $this->access->authorize($actor,'leave.request',$actor); $data=Validator::make($input,['leave_type_id'=>['required','integer',Rule::exists('leave_types','id')->where('organization_id',$actor->organization_id)->where('is_active',true)],'starts_on'=>['required','date_format:Y-m-d'],'ends_on'=>['required','date_format:Y-m-d','after_or_equal:starts_on'],'days'=>['required','numeric','gt:0'],'reason'=>['nullable','string','max:2000']])->validate();
        $year=substr($data['starts_on'],0,4); return DB::transaction(function()use($actor,$data,$year){abort_if(LeaveRequest::where('organization_id',$actor->organization_id)->where('membership_id',$actor->id)->whereNotIn('status',['rejected','cancelled'])->where(function($q)use($data){$q->whereBetween('starts_on',[$data['starts_on'],$data['ends_on']])->orWhereBetween('ends_on',[$data['starts_on'],$data['ends_on']])->orWhere(function($q)use($data){$q->where('starts_on','<=',$data['starts_on'])->where('ends_on','>=',$data['ends_on']);});})->exists(),422,'The requested dates overlap an existing leave request.'); $balance=LeaveBalance::where(['organization_id'=>$actor->organization_id,'membership_id'=>$actor->id,'leave_type_id'=>$data['leave_type_id'],'year'=>$year])->lockForUpdate()->first(); abort_unless($balance,422,'No leave balance is configured for this year.'); abort_if(((float)$balance->allocated_days-(float)$balance->reserved_days-(float)$balance->used_days)<(float)$data['days'],422,'Insufficient leave balance.'); $balance->increment('reserved_days',$data['days']); $request=LeaveRequest::create($data+['organization_id'=>$actor->organization_id,'membership_id'=>$actor->id,'status'=>'pending_manager']); $this->audit->record($actor->organization_id,$actor,'leave.requested','leave_request',$request->id); return $request;});
    }
    public function decide(OrganizationMembership $actor,LeaveRequest $request,string $decision,?string $comment=null):LeaveRequest
    {
        abort_unless($request->organization_id===$actor->organization_id,404); $ability=$request->status==='pending_manager'?'leave.approve_manager':'leave.approve_hr'; $this->access->authorize($actor,$ability,$request->membership); abort_if($request->membership_id===$actor->id,403,'A member cannot approve their own leave.'); abort_unless(in_array($decision,['approved','rejected'],true),422);
        return DB::transaction(function()use($actor,$request,$decision,$comment){$request=LeaveRequest::whereKey($request->id)->lockForUpdate()->firstOrFail(); $stage=$request->status==='pending_manager'?'manager':'hr'; DB::table('leave_approvals')->insert(['organization_id'=>$actor->organization_id,'leave_request_id'=>$request->id,'approver_membership_id'=>$actor->id,'stage'=>$stage,'decision'=>$decision,'comment'=>$comment,'created_at'=>now()]); $next=$decision==='rejected'?'rejected':($stage==='manager'?'pending_hr':'approved'); $request->status=$next; $request->save(); if($decision==='rejected'||$next==='approved'){ $balance=LeaveBalance::where(['membership_id'=>$request->membership_id,'leave_type_id'=>$request->leave_type_id])->where('year',$request->starts_on->format('Y'))->lockForUpdate()->first(); if($balance){$balance->decrement('reserved_days',$request->days); if($decision==='approved')$balance->increment('used_days',$request->days);}} $this->notifications->record($request->membership,'leave.decision:'.$request->id.':'.$decision,'Your leave request was '.$decision.'.'); $this->audit->record($actor->organization_id,$actor,'leave.'.$decision,'leave_request',$request->id); return $request;});
    }

    public function cancel(OrganizationMembership $actor, LeaveRequest $request): LeaveRequest
    {
        abort_unless($request->organization_id === $actor->organization_id && $request->membership_id === $actor->id, 404);
        abort_unless(in_array($request->status, ['pending_manager', 'pending_hr', 'approved'], true), 422, 'This leave request cannot be cancelled.');
        return DB::transaction(function () use ($actor, $request) { $request=LeaveRequest::whereKey($request->id)->lockForUpdate()->firstOrFail(); $balance=LeaveBalance::where(['membership_id'=>$request->membership_id,'leave_type_id'=>$request->leave_type_id])->where('year',$request->starts_on->format('Y'))->lockForUpdate()->first(); if($balance){$balance->decrement('reserved_days',$request->days); if($request->status==='approved')$balance->decrement('used_days',$request->days);} $request->update(['status'=>'cancelled']); $this->audit->record($actor->organization_id,$actor,'leave.cancelled','leave_request',$request->id); return $request; });
    }
}
